// Proves the fix is a no-op under the docs-screenshot driver's frozen clock:
// with Date.now() pinned to FIXED_CLOCK, isoHoursAgo(2) must still resolve to
// exactly FIXED_CLOCK - 2h — the value the old hardcoded base produced.
import { chromium } from '@playwright/test';

const FIXED_CLOCK = '2026-07-15T12:00:00.000Z';
const EXPECTED_CREATED_AT = '2026-07-15T10:00:00.000Z'; // what the old hardcoded base yielded

const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
await context.addInitScript(() => {
  try {
    sessionStorage.setItem('ezpds-harness-scenario', 'alert-active');
  } catch {}
});
const page = await context.newPage();
await page.clock.setFixedTime(new Date(FIXED_CLOCK));
await page.goto('http://localhost:5173/', { waitUntil: 'networkidle' });

const seeded = await page.evaluate(() => {
  const s = window.__harness.state();
  return { now: Date.now(), createdAt: s.identities[0].alerts[0].createdAt };
});

// Walk into the alert detail so the rendered countdown string is observable too.
await page.locator('button.alert-strip').first().click();
await page.getByText('remaining', { exact: false }).first().waitFor({ state: 'visible' });
const countdown = (await page.getByText('remaining', { exact: false }).first().innerText()).trim();

await browser.close();

const pass = seeded.createdAt === EXPECTED_CREATED_AT;
console.log(JSON.stringify({
  frozenNow: new Date(seeded.now).toISOString(),
  seededCreatedAt: seeded.createdAt,
  expectedCreatedAt: EXPECTED_CREATED_AT,
  renderedCountdown: countdown,
  identicalToOldHardcodedBase: pass,
}, null, 2));
process.exit(pass ? 0 : 1);

